// planReasonText is the sentence for a reason code in lang, or the code
// itself (shown literally) when the table does not have it.
func planReasonText(lang Language, code string) string {
	if t, ok := planReasonTexts[code]; ok {
		if lang == LanguageJA {
			return escMrkdwn(t.ja)
		}
		return escMrkdwn(t.en)
	}
	return litMrkdwn(code)
}
